pou.interface:
{implicit on}
{attribute 'linkalways'}
FUNCTION __memcmp__iec : INT
VAR_INPUT
ptr1: POINTER TO BYTE;
ptr2: POINTER TO BYTE;
diSize: DINT;
END_VAR
VAR
i: DINT;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}

    FOR (i := 0) TO diSize - 1 DO              
      IF ptr1[i] < ptr2[i] THEN
        __memcmp__iec := -1;
        RETURN;
      ELSIF ptr1[i] > ptr2[i] THEN
        __memcmp__iec := 1;
        RETURN; 
      END_IF
    END_FOR

    __memcmp__iec := 0;
    RETURN;

		{implicit off}
